/**
 * CP Template viewer.
 *
 * Vue 3 + Element Plus single-page app that renders the template JSON files
 * generated by .github/scripts/generate_templates.py.
 */
(function () {
    'use strict';

    const REPO_URL = 'https://github.com/wyf0722/CP_For_Fun';
    const REPO_BRANCH = 'main';

    const LANGUAGES = [
        { key: 'cpp', label: 'C++', sourceDir: 'Copypasta_Cpp' },
        { key: 'python', label: 'Python', sourceDir: 'Copypasta_Python' },
    ];

    const HIGHLIGHT_BY_EXT = { cpp: 'cpp', hpp: 'cpp', cc: 'cpp', py: 'python' };

    const THEME_STORAGE_KEY = 'cp-template:theme';
    const LANGUAGE_STORAGE_KEY = 'cp-template:language';

    const appRoot = document.getElementById('app');
    const templateNode = document.getElementById('app-template');

    if (!window.Vue || !window.ElementPlus || !templateNode) {
        if (appRoot) {
            appRoot.innerHTML =
                '<div class="boot-error">组件库加载失败，请检查网络后刷新页面。</div>';
        }
        return;
    }

    const { createApp } = window.Vue;
    const { ElMessage } = window.ElementPlus;

    /* ------------------------------- helpers ------------------------------- */

    // Turn an arbitrary string into a stable DOM-id-safe slug.
    function slugify(value) {
        return String(value).replace(/[^a-zA-Z0-9_-]/g, '_');
    }

    function inferHighlightLanguage(fileName, fallback) {
        const ext = fileName.split('.').pop().toLowerCase();
        return HIGHLIGHT_BY_EXT[ext] || fallback;
    }

    function languageLabel(highlightLanguage) {
        if (highlightLanguage === 'cpp') return 'C++';
        if (highlightLanguage === 'python') return 'Python';
        return 'Text';
    }

    function languageTagType(highlightLanguage) {
        if (highlightLanguage === 'cpp') return 'primary';
        if (highlightLanguage === 'python') return 'success';
        return 'info';
    }

    function escapeHtml(text) {
        return String(text)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;');
    }

    function highlightCode(code, highlightLanguage) {
        if (!window.hljs) return escapeHtml(code);
        const language = window.hljs.getLanguage(highlightLanguage)
            ? highlightLanguage
            : 'plaintext';
        try {
            return window.hljs.highlight(code, { language: language, ignoreIllegals: true }).value;
        } catch (error) {
            console.error('Highlight failed:', error);
            return escapeHtml(code);
        }
    }

    function buildSourceUrl(sourceDir, category, fileName) {
        const segments = category === 'root'
            ? [sourceDir, fileName]
            : [sourceDir].concat(category.split('/'), [fileName]);
        const path = segments.map(encodeURIComponent).join('/');
        return REPO_URL + '/blob/' + REPO_BRANCH + '/' + path;
    }

    // Map the raw JSON payload into the view model used by the template.
    function buildCategories(raw, languageKey) {
        const fallbackLanguage = languageKey === 'python' ? 'python' : 'cpp';
        const sourceDir = (LANGUAGES.find((item) => item.key === languageKey) || LANGUAGES[0]).sourceDir;

        return Object.entries(raw).map(([category, files]) => ({
            key: category,
            name: category === 'root' ? '根目录' : category,
            slug: slugify(category),
            files: Object.entries(files).map(([fileName, code]) => {
                const highlightLanguage = inferHighlightLanguage(fileName, fallbackLanguage);
                return {
                    path: category + '/' + fileName,
                    name: fileName,
                    code: code,
                    lines: code ? code.replace(/\n$/, '').split('\n').length : 0,
                    highlightLanguage: highlightLanguage,
                    langLabel: languageLabel(highlightLanguage),
                    tagType: languageTagType(highlightLanguage),
                    sourceUrl: buildSourceUrl(sourceDir, category, fileName),
                    // Filled on first expand so that big payloads stay cheap to render.
                    html: '',
                };
            }),
        }));
    }

    function readStorage(key) {
        try {
            return window.localStorage.getItem(key);
        } catch (error) {
            return null;
        }
    }

    function writeStorage(key, value) {
        try {
            window.localStorage.setItem(key, value);
        } catch (error) {
            /* Storage can be unavailable in private mode; ignore. */
        }
    }

    function isTypingTarget(target) {
        if (!target || !target.tagName) return false;
        const tag = target.tagName.toUpperCase();
        return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || target.isContentEditable;
    }

    async function writeClipboard(text) {
        if (navigator.clipboard && window.isSecureContext) {
            try {
                await navigator.clipboard.writeText(text);
                return true;
            } catch (error) {
                /* Fall through to the legacy path. */
            }
        }
        try {
            const area = document.createElement('textarea');
            area.value = text;
            area.setAttribute('readonly', '');
            area.style.position = 'fixed';
            area.style.top = '-2000px';
            area.style.opacity = '0';
            document.body.appendChild(area);
            area.select();
            const copied = document.execCommand('copy');
            document.body.removeChild(area);
            return copied;
        } catch (error) {
            return false;
        }
    }

    // Restart the "nothing changed" feedback animation on a button.
    function playShake(node) {
        if (!node) return;
        const target = node.closest ? node.closest('button') || node : node;
        target.classList.remove('shake');
        void target.offsetWidth;
        target.classList.add('shake');
        window.setTimeout(function () {
            target.classList.remove('shake');
        }, 520);
    }

    /* --------------------------------- app --------------------------------- */

    const app = createApp({
        // Compiled from the x-template block, so PascalCase and self-closing tags work.
        template: templateNode.innerHTML,

        data() {
            return {
                repoUrl: REPO_URL,
                languages: LANGUAGES,
                language: 'cpp',
                keyword: '',
                categories: [],
                loading: true,
                loadError: '',
                expanded: new Set(),
                copiedPath: '',
                activeCategory: '',
                isDark: false,
            };
        },

        computed: {
            languageLabel() {
                const current = LANGUAGES.find((item) => item.key === this.language);
                return current ? current.label : this.language;
            },

            totalCount() {
                return this.categories.reduce((sum, category) => sum + category.files.length, 0);
            },

            visibleCategories() {
                const keyword = this.keyword.trim().toLowerCase();
                if (!keyword) return this.categories;

                return this.categories
                    .map((category) => {
                        const categoryMatches = category.name.toLowerCase().includes(keyword);
                        return {
                            key: category.key,
                            name: category.name,
                            slug: category.slug,
                            files: categoryMatches
                                ? category.files
                                : category.files.filter((file) =>
                                      file.name.toLowerCase().includes(keyword)
                                  ),
                        };
                    })
                    .filter((category) => category.files.length > 0);
            },

            filteredCount() {
                return this.visibleCategories.reduce(
                    (sum, category) => sum + category.files.length,
                    0
                );
            },
        },

        created() {
            // Non-reactive caches: raw JSON payloads and copy feedback timer.
            this.templateCache = new Map();
            this.copyTimer = 0;
            this.scrollFrame = 0;
        },

        mounted() {
            this.initTheme();
            this.language = this.readInitialLanguage();
            this.loadTemplates(this.language);
            this.bindGlobalEvents();
        },

        beforeUnmount() {
            window.removeEventListener('scroll', this.handleScroll);
            document.removeEventListener('keydown', this.handleKeydown);
            window.clearTimeout(this.copyTimer);
        },

        methods: {
            /* ----------------------------- data ----------------------------- */

            readInitialLanguage() {
                const stored = readStorage(LANGUAGE_STORAGE_KEY);
                if (stored && LANGUAGES.some((item) => item.key === stored)) return stored;
                return 'cpp';
            },

            async loadTemplates(language, forceReload) {
                this.loading = true;
                this.loadError = '';

                try {
                    let raw = forceReload ? null : this.templateCache.get(language);
                    if (!raw) {
                        const response = await fetch('templates_' + language + '.json', {
                            cache: 'no-cache',
                        });
                        if (!response.ok) {
                            throw new Error(
                                '无法加载 ' + language + ' 模板（HTTP ' + response.status + '）'
                            );
                        }
                        raw = await response.json();
                        this.templateCache.set(language, raw);
                    }

                    this.categories = buildCategories(raw, language);
                    this.expanded = new Set();
                    this.activeCategory = this.categories.length ? this.categories[0].slug : '';
                    writeStorage(LANGUAGE_STORAGE_KEY, language);

                    this.$nextTick(() => {
                        this.scrollToHashTarget();
                        this.updateActiveCategory();
                    });
                } catch (error) {
                    console.error(error);
                    this.loadError = error.message || '模板加载失败';
                    this.categories = [];
                } finally {
                    this.loading = false;
                }
            },

            onLanguageChange(language) {
                this.keyword = '';
                this.loadTemplates(language);
            },

            findFile(path) {
                for (const category of this.categories) {
                    const file = category.files.find((item) => item.path === path);
                    if (file) return file;
                }
                return null;
            },

            /* --------------------------- highlight -------------------------- */

            ensureHighlighted(path) {
                const file = this.findFile(path);
                if (!file || file.html) return;
                file.html = highlightCode(file.code, file.highlightLanguage);
            },

            /* --------------------------- expand ----------------------------- */

            toggle(path) {
                if (this.expanded.has(path)) {
                    this.expanded.delete(path);
                    return;
                }
                this.expanded.add(path);
                this.ensureHighlighted(path);
            },

            setAll(show, event) {
                const files = this.visibleCategories.reduce(
                    (all, category) => all.concat(category.files),
                    []
                );
                let changed = false;

                files.forEach((file) => {
                    const isOpen = this.expanded.has(file.path);
                    if (show && !isOpen) {
                        this.expanded.add(file.path);
                        this.ensureHighlighted(file.path);
                        changed = true;
                    } else if (!show && isOpen) {
                        this.expanded.delete(file.path);
                        changed = true;
                    }
                });

                if (!changed) playShake(event && event.target);
            },

            /* ---------------------------- actions --------------------------- */

            async copy(file) {
                const copied = await writeClipboard(file.code);
                if (!copied) {
                    ElMessage.error('复制失败，请手动选择代码');
                    return;
                }
                this.copiedPath = file.path;
                window.clearTimeout(this.copyTimer);
                this.copyTimer = window.setTimeout(() => {
                    this.copiedPath = '';
                }, 1800);
                ElMessage.success('已复制 ' + file.name);
            },

            download(file) {
                const blob = new Blob([file.code], { type: 'text/plain;charset=utf-8' });
                const url = URL.createObjectURL(blob);
                const anchor = document.createElement('a');
                anchor.href = url;
                anchor.download = file.name;
                document.body.appendChild(anchor);
                anchor.click();
                document.body.removeChild(anchor);
                window.setTimeout(() => URL.revokeObjectURL(url), 1000);
                ElMessage.success('已下载 ' + file.name);
            },

            /* --------------------------- navigation ------------------------- */

            scrollToCategory(slug) {
                const target = document.getElementById('category-' + slug);
                if (!target) return;
                target.scrollIntoView({ behavior: 'smooth', block: 'start' });
                this.activeCategory = slug;
                try {
                    window.history.replaceState(null, '', '#category-' + slug);
                } catch (error) {
                    /* replaceState throws on file:// origins; the scroll still works. */
                }
            },

            scrollToHashTarget() {
                const hash = window.location.hash || '';
                if (hash.indexOf('#category-') !== 0) return;
                const target = document.getElementById(hash.slice(1));
                if (target) target.scrollIntoView({ block: 'start' });
            },

            updateActiveCategory() {
                const sections = document.querySelectorAll('[data-category]');
                if (!sections.length) return;

                const threshold = 160;
                let current = sections[0].dataset.category;
                for (const section of sections) {
                    if (section.getBoundingClientRect().top <= threshold) {
                        current = section.dataset.category;
                    } else {
                        break;
                    }
                }
                if (this.activeCategory !== current) this.activeCategory = current;
            },

            /* ----------------------------- theme ---------------------------- */

            initTheme() {
                const stored = readStorage(THEME_STORAGE_KEY);
                const prefersDark =
                    window.matchMedia &&
                    window.matchMedia('(prefers-color-scheme: dark)').matches;
                this.applyTheme(stored ? stored === 'dark' : Boolean(prefersDark));
            },

            applyTheme(dark) {
                this.isDark = dark;
                document.documentElement.classList.toggle('dark', dark);

                const lightSheet = document.getElementById('hljs-light');
                const darkSheet = document.getElementById('hljs-dark');
                if (lightSheet) lightSheet.disabled = dark;
                if (darkSheet) darkSheet.disabled = !dark;

                writeStorage(THEME_STORAGE_KEY, dark ? 'dark' : 'light');
            },

            toggleTheme() {
                this.applyTheme(!this.isDark);
            },

            /* ---------------------------- events ---------------------------- */

            bindGlobalEvents() {
                this.handleScroll = () => {
                    if (this.scrollFrame) return;
                    this.scrollFrame = window.requestAnimationFrame(() => {
                        this.scrollFrame = 0;
                        this.updateActiveCategory();
                    });
                };
                window.addEventListener('scroll', this.handleScroll, { passive: true });

                this.handleKeydown = (event) => {
                    const isModifier = event.ctrlKey || event.metaKey;
                    if (isModifier && event.key.toLowerCase() === 'k') {
                        event.preventDefault();
                        this.focusSearch();
                        return;
                    }
                    if (event.key === 'Escape' && this.keyword) {
                        this.keyword = '';
                        return;
                    }
                    if (event.key === '/' && !isTypingTarget(event.target)) {
                        event.preventDefault();
                        this.focusSearch();
                    }
                };
                document.addEventListener('keydown', this.handleKeydown);
            },

            focusSearch() {
                const input = this.$refs.searchInput;
                if (input && input.focus) input.focus();
            },
        },
    });

    app.use(window.ElementPlus);

    if (window.ElementPlusIconsVue) {
        Object.entries(window.ElementPlusIconsVue).forEach(([name, component]) => {
            app.component(name, component);
        });
    }

    app.mount('#app');
})();
